vector<int> parse_csv_ints(const string& s) {
    vector<int> result;
    stringstream ss(s);
    string segment;

    while (getline(ss, segment, ',')) {
        // Trim leading whitespace
        size_t start = 0;
        while (start < segment.size() && isspace(static_cast<unsigned char>(segment[start]))) {
            ++start;
        }

        // Trim trailing whitespace
        size_t end = segment.size();
        while (end > start && isspace(static_cast<unsigned char>(segment[end - 1]))) {
            --end;
        }

        // Skip empty segments
        if (start >= end) {
            continue;
        }

        string trimmed = segment.substr(start, end - start);

        // Try to parse as integer
        try {
            size_t pos = 0;
            int value = stoi(trimmed, &pos);
            // Ensure the entire trimmed string was consumed (no extra characters)
            if (pos == trimmed.size()) {
                result.push_back(value);
            }
        } catch (...) {
            // Skip invalid numbers
            continue;
        }
    }

    return result;
}
