def eval_expr(expr: str) -> int:
    """
    Evaluate an integer arithmetic expression with +, -, *, /, parentheses.
    Integer division truncates toward zero.
    """
    # Remove all spaces
    expr = expr.replace(' ', '')

    pos = 0
    n = len(expr)

    def parse_expression():
        """Parse addition and subtraction (lowest precedence)."""
        nonlocal pos
        result = parse_term()
        while pos < n and expr[pos] in '+-':
            op = expr[pos]
            pos += 1
            right = parse_term()
            if op == '+':
                result += right
            else:
                result -= right
        return result

    def parse_term():
        """Parse multiplication and division (higher precedence)."""
        nonlocal pos
        result = parse_factor()
        while pos < n and expr[pos] in '*/':
            op = expr[pos]
            pos += 1
            right = parse_factor()
            if op == '*':
                result *= right
            else:
                # Truncate toward zero
                if result * right < 0:
                    result = -((-result) // right) if result < 0 else -(result // (-right))
                    # Simpler: use int() on float division or manual truncation
                    # Actually, let's use a cleaner approach
                    result = int(result / right) if False else truncate_div(result, right)
        return result

    def truncate_div(a, b):
        """Truncate division toward zero."""
        if b == 0:
            raise ZeroDivisionError("division by zero")
        result = abs(a) // abs(b)
        if (a < 0) ^ (b < 0):
            result = -result
        return result

    def parse_factor():
        """Parse a number, unary +/-, or parenthesized expression."""
        nonlocal pos
        if pos < n and expr[pos] == '(':
            pos += 1  # skip '('
            result = parse_expression()
            if pos < n and expr[pos] == ')':
                pos += 1  # skip ')'
            return result
        elif pos < n and expr[pos] == '+':
            pos += 1
            return parse_factor()
        elif pos < n and expr[pos] == '-':
            pos += 1
            return -parse_factor()
        else:
            # Parse a number
            start = pos
            while pos < n and expr[pos].isdigit():
                pos += 1
            return int(expr[start:pos])

    return parse_expression()
